-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Taking overall responsibility for quality on the audit engagement","Setting the firm''s overall quality management policies and standards","Approving the firm''s human resources policies and procedures","Conducting firm-wide inspections of all completed audit engagements"]$EXPL$::jsonb,
